  if (o.addCity) TB.addCityOpen = true;
  if (TB.preselect){ const cid = TB.preselect.cityId; const src = TB.preselect.sourceType === 'community' ? 'public' : 'mine'; const list = await tbLoadPlaces(cid, src); const hit = list.find(function(p){ return p.ref.subcatId === TB.preselect.subcatId && p.ref.placeId === TB.preselect.placeId && (p.ref.sourceUid || null) === (TB.preselect.sourceUid || null); }); if (hit){ TB.picked[cid] = TB.picked[cid] || {}; TB.picked[cid][hit.key] = tbEntryOf(hit); } else if (src === 'mine' && tripSectionOf(TB.preselect.subcatId) === 'stay'){ const stayList = await tbLoadPlaces(cid, 'stay'); const sh = stayList.find(function(p){ return p.ref.subcatId === TB.preselect.subcatId && p.ref.placeId === TB.preselect.placeId; }); const cc = TB.cities.find(function(c){ return c.cityId === cid; }); if (sh && cc){ cc.stay = { name: sh.name, geo: sh.geo || null }; showToast('Set as where you stay'); } } TB.preselect = null; } /* ب-٨: مكان من تصنيف Stay = الإقامة لا محطة */
