/* ═══ r92 (ق١٠-٢٨-٠٣ · «نفذ» ٢٨ أكتوبر ١٢:٥٠): يوم Day trip — محرّر خطّي: ملاحظة التنقل · الخروج والعودة · الانطلاق → المحطات (New stop · From My places) → العودة · لكل رِجل وسيلة ودقائق وملاحظة · لكل محطة مدة وعلم optional ووقت مثبَّت ═══ */
function tbDTDay(){ return (TB && TB.plan && TB.plan.days && TB.plan.days[0] && TB.plan.days[0].mode === 'daytrip') ? TB.plan.days[0] : null; }
function tbDTRoute(){ const d = tbDTDay(); if (!d) return null; return tripRouteDoc(tbEnsureTrip(), d); }
function tbSetTripName(v){ if (!TB) return; TB.title = String(v || '').trim().slice(0, 80); tbSave(); } /* r93-١ (ق١٠-٢٩-٠١): Trip name يكتب title */
function tbNameHtml(){ return TB.dayPlan ? '<label class="flabel">Trip name</label><input type="text" class="modal-input" id="tbTripName" maxlength="80" placeholder="' + (TB.dayTrip ? 'e.g. Gstaad by GoldenPass' : 'e.g. Old town & lake') + '" value="' + attrStr(TB.title || '') + '" onchange="tbSetTripName(this.value)">' : ''; }
function tbDTTime(field, v){ const r = tbDTRoute(); if (!r) return; r[field] = (tripMinutesOf(v) !== null) ? String(v) : null; tbSave(); tbRender(); }
function tbDTLegMode(key, v){ const r = tbDTRoute(); if (!r) return; const L = r.legs[key] = r.legs[key] || { mode: null, minutes: null }; L.mode = TRIP_MODE_LABEL[v] ? v : null; tbSave(); tbRender(); }
function tbDTLegMin(key, v){ const r = tbDTRoute(); if (!r) return; const L = r.legs[key] = r.legs[key] || { mode: null, minutes: null }; const n = parseInt(v, 10); L.minutes = (!isNaN(n) && n >= 0 && n <= 1440) ? n : null; tbSave(); tbRender(); }
function tbDTLegNote(key, v){ const r = tbDTRoute(); if (!r) return; const L = r.legs[key] = r.legs[key] || { mode: null, minutes: null }; const t = String(v || '').trim().slice(0, 200); if (t) L.note = t; else delete L.note; tbSave(); }
function tbDTStay(id, v){ const r = tbDTRoute(); if (!r) return; const n = parseInt(v, 10); if (!isNaN(n) && n >= 0 && n <= 1440) r.stays[id] = n; else delete r.stays[id]; tbSave(); tbRender(); }
function tbDTMove(id, dir){ const d = tbDTDay(); if (!d) return; const i = d.stops.findIndex(function(x){ return x.id === id; }); const j = i + dir; if (i < 0 || j < 0 || j >= d.stops.length) return; tbSnapshot(); const x = d.stops.splice(i, 1)[0]; d.stops.splice(j, 0, x); tbSave(); tbRender(); }
async function tbDTRemove(id){ const d = tbDTDay(); if (!d) return; const e = d.stops.find(function(x){ return x.id === id; }); if (!e) return; if (!(await mpConfirm('Remove ' + (e.name || 'this stop') + ' from the day?', { title: 'Remove stop', ok: 'Remove', danger: true }))) return; tbSnapshot(); tripDetach(TB.plan, id); if (!tripIsStop(e) && e.ref && e.ref.cityId && TB.picked[e.ref.cityId]) delete TB.picked[e.ref.cityId][tbKey(e.ref)]; tbSave(); tbRender(); }
function tbDTToggleOptional(id){ const d = tbDTDay(); if (!d) return; const e = d.stops.find(function(x){ return x.id === id; }); if (!e) return; e.optional = !e.optional; tbSave(); tbRender(); }
function tbDayTripHtml(day){
  const city = TB.cities[0] || {}; const trip = tbTrip() || { dayRoutes: {} }; const s = tripDaySchedule(trip, day, city); const route = tripRouteOf(trip, day); const tm = function(m){ return (typeof m === 'number') ? tripHHMMx(m) : '—'; }; const n = day.stops.length;
  let h = '<div class="chiprow tb-top"><button type="button" class="chip" onclick="TB.stage = 1; tbRender()">Setup</button><button type="button" class="chip" ' + (TB.undo.length ? '' : 'disabled') + ' onclick="tbUndo()" title="Undo last change">↶</button></div>';
  h += '<div class="tb-note">🚞 <b>Day trip</b> · ' + escapeHtml(city.cityName || '') + ' · ' + n + (n === 1 ? ' stop' : ' stops') + ' · <span class="dim">a linear route — your order, no rhythm</span></div>';
  h += tbNameHtml();
  h += '<div class="tb-grid2"><label class="flabel">Leave<span class="tb-dt"><input type="time" class="modal-input" value="' + attrStr(route.leave || (typeof day.from === 'number' ? tripHHMM(day.from) : '')) + '" onchange="tbDTTime(\'leave\', this.value)"></span></label><label class="flabel">Back by<span class="tb-dt"><input type="time" class="modal-input" value="' + attrStr(route.backBy || (typeof day.to === 'number' ? tripHHMM(day.to) : '')) + '" onchange="tbDTTime(\'backBy\', this.value)"></span></label></div>';
  const start = tripDayStart(day, city); if (!start) h += '<div class="tb-hint">No start point yet — set <b>Start from</b> in Setup (the station, your hotel…) and the return leg appears.</div>';
  let k = 0; s.steps.forEach(function(st){
    if (st.leg){ const L = st.leg; const isReturn = st.kind === 'end'; h += '<div class="tr-leg' + (L.missing ? ' missing' : '') + '"' + (isReturn ? ' style="border-left-style:solid;"' : '') + '><span class="tr-leg-km">' + (isReturn ? 'return' : (L.km !== null ? tripKmLabel(L.km) : '—')) + '</span><select class="modal-input" style="display:inline-block; width:auto; margin:0; padding:3px 6px; font-size:11.5px;" onchange="tbDTLegMode(\'' + attrStr(L.key) + '\', this.value)">' + TRIP_MODES.map(function(m){ return '<option value="' + m[0] + '"' + (m[0] === L.mode ? ' selected' : '') + '>' + (TRIP_MODE_ICON[m[0]] || '') + ' ' + m[1] + '</option>'; }).join('') + '</select><label class="tr-min"><input type="number" class="modal-input" min="0" max="1440" inputmode="numeric" placeholder="min" value="' + (L.missing ? '' : L.minutes) + '" onchange="tbDTLegMin(\'' + attrStr(L.key) + '\', this.value)"> min</label><input type="text" class="modal-input" style="flex:1 1 100%; margin:4px 0 0; padding:3px 8px; font-size:11.5px;" maxlength="200" placeholder="note — line, via, what to see on the way" value="' + attrStr(L.note || '') + '" onchange="tbDTLegNote(\'' + attrStr(L.key) + '\', this.value)"></div>'; }
    if (st.kind === 'stay') h += '<div class="tr-stay"><span>🏨 <b dir="auto">' + escapeHtml(st.name) + '</b> <span class="dim">· start</span></span><span class="tr-time">leave ' + tm(tripMinutesOf(s.leave)) + '</span></div>';
    else if (st.kind === 'end') h += '<div class="tr-stay end"><span>🏨 <b dir="auto">' + escapeHtml(st.name) + '</b></span><span class="tr-time">' + (st.arrive !== null ? 'back ' + tm(st.arrive) + (s.backBy ? (s.late ? ' · after ' + escapeHtml(s.backBy) + ' ✗' : ' · before ' + escapeHtml(s.backBy) + ' ✓') : '') : 'back —') + '</span></div>';
    else if (st.kind === 'stop'){ k++; const e = st.entry || {}; const isStop = tripIsStop(e); const kind = isStop ? tripStopKind(e.ref.kind) : null; const sub = [isStop ? kind[2].toLowerCase() : 'from My places', e.optional ? '<b>optional — if time allows</b>' : '', e.fixedAt ? 'at ' + escapeHtml(e.fixedAt) + ' (fixed)' : ''].filter(Boolean).join(' · ');
      h += '<div class="tr-stop' + (e.optional ? ' opt' : '') + '" id="tbStop_' + attrStr(e.id) + '"><span class="pc-chip trip-num">' + k + '</span><div class="tr-stop-b"><b dir="auto">' + (isStop ? kind[1] + ' ' : '') + escapeHtml(e.name) + '</b><span class="tr-sub">' + sub + '</span>' + (e.about ? '<span class="tr-sub" dir="auto" style="opacity:.9;">' + escapeHtml(e.about) + '</span>' : '') + '<span class="tr-times">' + tm(st.arrive) + ' → ' + tm(st.depart) + '</span><span class="chiprow" style="margin-top:4px; gap:4px; overflow:visible; flex-wrap:wrap;"><button type="button" class="chip sm" onclick="tbDTMove(\'' + attrStr(e.id) + '\', -1)" ' + (k === 1 ? 'disabled' : '') + ' aria-label="Move up">▲</button><button type="button" class="chip sm" onclick="tbDTMove(\'' + attrStr(e.id) + '\', 1)" ' + (k === n ? 'disabled' : '') + ' aria-label="Move down">▼</button>' + (isStop ? '<button type="button" class="chip sm" onclick="tbStopSheet(\'' + attrStr(e.id) + '\')">✎ Edit</button>' : '') + '<button type="button" class="chip sm' + (e.optional ? ' on' : '') + '" onclick="tbDTToggleOptional(\'' + attrStr(e.id) + '\')">optional</button><button type="button" class="chip sm" onclick="tbDTRemove(\'' + attrStr(e.id) + '\')" aria-label="Remove">✕</button></span></div><label class="tr-min">stay <input type="number" class="modal-input" min="0" max="1440" inputmode="numeric" value="' + st.minutes + '" onchange="tbDTStay(\'' + attrStr(e.id) + '\', this.value)"> min</label></div>'; }
  });
  if (!n) h += '<div class="mp-empty mini">No stops yet — add the first one.</div>';
  h += '<div class="chiprow" style="margin:10px 0 0; flex-wrap:wrap; overflow:visible; gap:6px;"><button type="button" class="chip on" style="flex:none;" onclick="tbStopSheet(null)">＋ New stop</button><button type="button" class="chip" style="flex:none;" onclick="tbOpenPick(\'' + attrStr(city.cityId || '') + '\')">＋ From My places</button></div><div class="tb-hint">New stop is kept inside this day plan, not in My places. From My places picks saved places (a restaurant in the village).</div>';
  if (n) h += tripRouteStatusHtml(s);
  h += '<button type="button" class="cta wide tb-cta" onclick="tbApprove()">' + ((tbTrip() || {}).status === 'approved' ? 'Done ✓' : 'Approve this day ✓') + '</button>';
  return h;
}
/* ── ورقة المحطة (New stop · Edit) ── */
let tbStopDraft = null; /* { id|null, name, kind, geo, where, about, optional, fixedAt } */
async function tbStopSheet(id){ const d = tbDTDay(); if (!d) return; const e = id ? d.stops.find(function(x){ return x.id === id; }) : null; tbStopDraft = e ? { id: e.id, name: e.name, url: e.url || '', kind: (e.ref && e.ref.kind) || 'other', geo: e.geo ? Object.assign({}, e.geo) : null, where: e.geo ? 'kept' : '', about: e.about || '', optional: !!e.optional, fixedAt: e.fixedAt || '' } : { id: null, name: '', url: '', kind: 'town', geo: null, where: '', about: '', optional: false, fixedAt: '' }; const city = TB.cities[0] || {}; const cc = (typeof plCountryCode === 'function' && city.cityId) ? plCountryCode((cityListAllCities().find(function(x){ return x.id === city.cityId; }) || {}).country || '') : ''; let towns = []; try{ towns = cc ? await gazLoad(cc) : []; }catch(_){} tbStopDraft.towns = towns; tbStopRender(); }
function tbStopRender(){ const dr = tbStopDraft; if (!dr) return; const bd = document.getElementById('dashBackdrop'); const body = document.getElementById('dashBody'); if (!bd || !body) return; bd.classList.add('show'); dashSet(dr.id ? '✎ Stop' : '＋ New stop', null);
  body.innerHTML = '<div id="tbStopBody"><div style="font-size:12.5px; line-height:1.5;" class="dim">Kept inside this day plan — not saved to My places.</div>'
    + '<label class="flabel dim">Google Maps link</label><div style="display:flex; gap:6px; align-items:center;"><input type="text" class="modal-input" id="tbStopUrl" style="flex:1; text-align:left; margin:0;" placeholder="https://maps.app.goo.gl/… — the name reads from it" value="' + attrStr(dr.url || '') + '" onpaste="tbStopOnPaste(event)" onchange="tbStopUrlChanged(this.value)"><button type="button" class="pl-actbtn" onclick="tbStopPasteUrl()" title="Paste what Google Maps shared">📋</button></div>' /* r93-٣ (ق١٠-٢٩-٠١): الخانات الأربع كنافذة Add place: الرابط · الرمز/البلدة · الاسم · النوع */
    + '<label class="flabel dim">Plus code · or a town from our list</label><div style="display:flex; gap:6px; flex-wrap:wrap;"><input type="text" class="modal-input" id="tbStopPlus" style="flex:1 1 140px; margin:0;" placeholder="paste a Plus code / pin link" autocapitalize="characters" autocorrect="off" onchange="tbStopPlusPick(this.value)"><input type="text" class="modal-input" id="tbStopTown" list="tbStopTowns" style="flex:1 1 140px; margin:0;" placeholder="or a town…" onchange="tbStopTownPick(this.value)"><datalist id="tbStopTowns">' + (dr.towns || []).slice(0, 400).map(function(c){ return '<option value="' + attrStr(c.n) + '">'; }).join('') + '</datalist></div>'
    + '<div class="dim" style="font-size:11.5px; margin-top:4px;" id="tbStopWhere">' + (dr.geo ? '📍 ' + escapeHtml(dr.where === 'kept' ? 'pinned' : dr.where) + ' · ' + dr.geo.lat.toFixed(4) + ', ' + dr.geo.lng.toFixed(4) + ' <button type="button" class="chip sm" onclick="tbStopDraft.geo = null; tbStopDraft.where = \'\'; tbStopRender()">✕ clear</button>' : 'No pin yet — a pin puts it on the trip map and gives the legs a distance.') + '</div>'
    + '<label class="flabel dim">Name</label><input type="text" class="modal-input" id="tbStopName" maxlength="120" placeholder="reads from the link · or type it" value="' + attrStr(dr.name) + '" oninput="tbStopDraft.name = this.value">'
    + '<label class="flabel dim">Kind</label><div class="chiprow" style="flex-wrap:wrap; overflow:visible; gap:6px;">' + TRIP_STOP_KINDS.map(function(x){ return '<button type="button" class="chip' + (dr.kind === x[0] ? ' on' : '') + '" style="flex:none;" onclick="tbStopDraft.kind = \'' + x[0] + '\'; tbStopRender()">' + x[1] + ' ' + x[2] + '</button>'; }).join('') + '</div>'
    + '<label class="flabel dim">About</label><textarea class="modal-input" id="tbStopAbout" rows="2" maxlength="500" placeholder="what it is, what to see — one or two lines" oninput="tbStopDraft.about = this.value">' + escapeHtml(dr.about) + '</textarea>'
    + '<div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap; margin-top:6px;"><button type="button" class="chip tog' + (dr.optional ? ' on' : '') + '" onclick="tbStopDraft.optional = !tbStopDraft.optional; tbStopRender()">Optional — if time allows</button><label class="tr-min">fixed time <input type="time" class="modal-input" value="' + attrStr(dr.fixedAt || '') + '" onchange="tbStopDraft.fixedAt = this.value"></label></div>'
    + '<button type="button" class="cta" style="display:block; width:100%; margin-top:12px;" onclick="tbStopSave()">' + (dr.id ? 'Save' : 'Add stop') + '</button><button type="button" class="btn btn-ghost" style="margin-top:8px; padding:7px 14px; font-size:12px;" onclick="tbStopDraft = null; closeModalById(\'dashBackdrop\')">Cancel</button></div>'; }
function tbStopTownPick(v){ const dr = tbStopDraft; if (!dr) return; const n = pickerNormalize(v || ''); const row = (dr.towns || []).find(function(c){ return pickerNormalize(c.n) === n || (c.a || []).some(function(a){ return pickerNormalize(a) === n; }); }); if (row && typeof row.lat === 'number'){ dr.geo = { lat: row.lat, lng: row.lng }; dr.where = row.n; if (!dr.name.trim()) dr.name = row.n; } else if (v && v.trim()) showToast('Not in our city list — paste a Plus code instead'); tbStopRender(); }
function tbStopOnPaste(ev){ try{ const t = ((ev.clipboardData || window.clipboardData) || {}).getData ? (ev.clipboardData || window.clipboardData).getData('text') : ''; if (!t || !t.trim()) return; ev.preventDefault(); tbStopReadShare(t.trim()); }catch(_){} } /* r93-٣ */
async function tbStopPasteUrl(){ try{ const t = await navigator.clipboard.readText(); if (!t || !t.trim()){ showToast('Clipboard is empty'); return; } tbStopReadShare(t.trim()); }catch(e){ showToast('Could not access clipboard — paste into the link field'); } } /* r93-٣ */
function tbStopUrlChanged(v){ const dr = tbStopDraft; if (!dr) return; dr.url = String(v || '').trim(); if (/^https?:\/\//.test(dr.url) && !dr.name.trim()) tbStopResolve(dr.url); } /* r93-٣ */
async function tbStopReadShare(text){ const dr = tbStopDraft; if (!dr) return; const r = parseMapsShare(text); if (!r.url){ showToast('No link found in the pasted text'); return; } dr.url = r.url; if (r.name && !dr.name.trim()) dr.name = r.name; try{ const pt = await tkPlusPoint(text); if (pt && !pt.err && typeof pt.lat === 'number' && !dr.geo){ dr.geo = { lat: +(+pt.lat).toFixed(5), lng: +(+pt.lng).toFixed(5) }; dr.where = pt.how === 'code' ? 'Plus code' : 'pin link'; } }catch(_){} tbStopRender(); if (!dr.name.trim()) await tbStopResolve(r.url); else showToast('Read ✓ — name filled'); } /* r93-٣: نص المشاركة → الرابط والاسم (والموضع إن حمله الرابط) */
async function tbStopResolve(url){ const dr = tbStopDraft; if (!dr) return; try{ const r = await mpData.geo.resolve(url); if (r && r.name && dr === tbStopDraft && !dr.name.trim()){ dr.name = String(r.name).slice(0, 120); const el = document.getElementById('tbStopName'); if (el) el.value = dr.name; showToast('Name read from the link ✓'); } }catch(e){ mpSwallow(e, 'stop-resolve'); } } /* r93-٣: الاسم من الرابط عبر العامل (بلا مساس به) */
async function tbStopPlusPick(v){ const dr = tbStopDraft; if (!dr || !v || !v.trim()) return; const r = await tkPlusPoint(v); if (!r || r.err){ showToast((r && r.err) || 'Nothing to read'); return; } dr.geo = { lat: +(+r.lat).toFixed(5), lng: +(+r.lng).toFixed(5) }; dr.where = r.how === 'code' ? 'Plus code' : r.how === 'link' ? 'pin link' : 'coordinates'; tbStopRender(); }
function tbStopSave(){ const dr = tbStopDraft; const d = tbDTDay(); if (!dr || !d) return; const name = String(dr.name || '').trim(); if (!name){ showToast('Give the stop a name'); return; } tbSnapshot(); if (dr.id){ const e = d.stops.find(function(x){ return x.id === dr.id; }); if (e){ e.name = name.slice(0, 120); e.url = String(dr.url || '').trim().slice(0, 400); e.ref = { sourceType: 'stop', kind: tripStopKind(dr.kind)[0] }; e.geo = dr.geo ? { lat: dr.geo.lat, lng: dr.geo.lng } : null; e.about = String(dr.about || '').trim().slice(0, 500); e.optional = !!dr.optional; e.fixedAt = (tripMinutesOf(dr.fixedAt) !== null) ? String(dr.fixedAt) : null; } } else d.stops.push(tripNewStop({ name: name, url: dr.url, kind: dr.kind, geo: dr.geo, about: dr.about, optional: dr.optional, fixedAt: dr.fixedAt })); tbStopDraft = null; closeModalById('dashBackdrop'); tbSave(); tbRender(); try{ mpTripCount('stopsAdded', 1); }catch(_){} }
